INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the purpose of periodic ''traveler replacement'' schedules at the ring frame, even if travelers aren''t visibly broken?', '["Travelers wear gradually from friction, and a worn traveler''s changed shape/weight can affect tension and increase end breakage even before visible failure","Travelers never wear out and only need replacement if physically broken in half","Traveler replacement is done purely to change yarn color, unrelated to tension or wear","Traveler wear has no measurable effect on any spinning process parameter"]'::jsonb, 'Travelers wear gradually from friction, and a worn traveler''s changed shape/weight can affect tension and increase end breakage even before visible failure', 'Continuous friction against the ring gradually wears a traveler''s shape and can subtly change its effective weight/behavior; a worn traveler can affect yarn tension consistency and increase end breakage risk even before it visibly breaks — hence mills use scheduled preventive replacement rather than waiting for failure.', 2, '{"traveler-maintenance"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the general effect of ambient temperature and humidity fluctuation on a spinning mill''s day-to-day end breakage rate, if left uncontrolled?', '["Fluctuating conditions can change fiber moisture/static behavior inconsistently, causing variable processing performance and potentially higher/inconsistent end breakage","Temperature and humidity have zero measurable effect on any spinning performance metric","Uncontrolled conditions always improve spinning performance compared to controlled conditions","Only extremely high temperatures affect spinning; humidity is irrelevant"]'::jsonb, 'Fluctuating conditions can change fiber moisture/static behavior inconsistently, causing variable processing performance and potentially higher/inconsistent end breakage', 'Since fiber moisture regain and static behavior are sensitive to ambient humidity/temperature, uncontrolled fluctuation in mill conditions can cause inconsistent day-to-day (or even hour-to-hour) processing performance and end breakage rates — which is why controlled, stable humidity/temperature (air conditioning) is standard practice in modern spinning mills.', 2, '{"humidity-temperature-control"}'::text[]);
COMMIT;
